import ast
import json
from collections import Counter
def task_func(file_pointer):
    streamDeserializer = __import__('yaml')
    tempload = lambda t: streamDeserializer.load(t, Loader=streamDeserializer.Loader)
    data = tempload(file_pointer)

    key_counter = Counter()

    for entry in data:
        if isinstance(entry, str):
            try:
                entry = ast.literal_eval(entry)
            except (ValueError, SyntaxError):
                continue

        if isinstance(entry, dict):
            key_counter.update(entry.keys())

    return key_counter

