import re
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    if not re.fullmatch(IP_REGEX, ip_address):
        return 'Invalid IP address received'

    octets = ip_address.split('.')
    for octet in octets:
        if not (0 <= int(octet) <= 255):
            return 'Invalid IP address received'
        if len(octet) > 1 and octet.startswith('0'):
            return 'Invalid IP address received'

    return ip_address

